const fmt = (n, c="ALL") => n == null ? tr("Price unavailable") : `${new Intl.NumberFormat(language==="sq"?"sq-AL":"en-US", {maximumFractionDigits:c==="EUR"?2:0}).format(n)} ${c === "ALL" ? "Lekë" : c === "EUR" ? "€" : c}`;
const safe = (s="") => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const storeMark = store => store.split(/\s+/).map(part=>part[0]).join("").slice(0,2).toUpperCase();
const storeKey = store => store.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
const storeBadge = store => {const mark=storeMark(store),domain=retailerDomains[store];return `<i class="store-symbol ${storeKey(store)}"><b>${mark}</b><img src="https://www.google.com/s2/favicons?domain=${domain}&sz=64" alt="" loading="lazy" onload="this.previousElementSibling.hidden=true" onerror="this.previousElementSibling.style.display='block';this.remove()"></i>`;};
function renderRetailerPicker(){
  const root=$("#retailer-picker-list");if(!root)return;
  root.innerHTML=retailers.map(name=>`<button type="button" class="retailer-choice ${selectedRetailers.has(name)?"selected":""}" data-select-retailer="${safe(name)}" aria-pressed="${selectedRetailers.has(name)}"><span class="retailer-choice-top">${storeBadge(name)}<i class="retailer-choice-tick">✓</i></span><b>${safe(name)}</b><small>${safe(retailerDomains[name])}</small></button>`).join("");
  const all=$("#retailer-select-all");all.checked=selectedRetailers.size===retailers.length;all.indeterminate=selectedRetailers.size>0&&selectedRetailers.size<retailers.length;
  $("#retailer-selection-count").textContent=`${selectedRetailers.size} ${tr("stores selected")}`;$("#stat-stores").textContent=selectedRetailers.size;
}
const comparablePrice = item => item?.price == null ? Infinity : Number(item.price) * (item.currency === "EUR" ? EUR_TO_ALL : 1);
function tr(value){return language==="sq"?(sq[value]||value):Object.keys(sq).find(k=>sq[k]===value)||value;}
function applyLanguage(){document.documentElement.lang=language==="sq"?"sq":"en";const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const old=node.nodeValue.trim();if(!old)continue;const translated=tr(old);if(translated!==old)node.nodeValue=node.nodeValue.replace(old,translated);}document.querySelectorAll("input[placeholder],button[aria-label],a[aria-label],select[aria-label]").forEach(el=>{const attr=el.hasAttribute("placeholder")?"placeholder":"aria-label";el.setAttribute(attr,tr(el.getAttribute(attr)));});const button=$("#language-toggle");if(button){if(button.dataset.lang!==language){button.innerHTML=`<span class="language-flags" aria-hidden="true"><svg class="language-flag ${language==="sq"?"selected":""}" viewBox="0 0 60 40"><rect width="60" height="40" fill="#e41e20"/><path d="M15 11 25 16 23 23 30 19 37 23 35 16 45 11 34 12 30 5 26 12zM15 29l10-5 5 4 5-4 10 5-11-1-4 6-4-6z" fill="#111"/></svg><svg class="language-flag ${language==="en"?"selected":""}" viewBox="0 0 60 40"><rect width="60" height="40" fill="#173778"/><path d="M0 0 60 40M60 0 0 40" stroke="#fff" stroke-width="9"/><path d="M0 0 60 40M60 0 0 40" stroke="#c8102e" stroke-width="4"/><path d="M30 0v40M0 20h60" stroke="#fff" stroke-width="13"/><path d="M30 0v40M0 20h60" stroke="#c8102e" stroke-width="7"/></svg></span>`;button.dataset.lang=language;}button.title=language==="en"?"Shqip":"English";button.setAttribute("aria-label",button.title);}const title=language==="en"?"PricePal — Compare smarter. Pay less.":"PricePal — Krahaso më zgjuar. Paguaj më pak.";document.title=title;}
const relative = value => { if(!value) return "Not checked"; const d=Math.max(0,Date.now()-new Date(value).getTime()); if(d<60000)return "Just checked";if(d<3600000)return `${Math.floor(d/60000)} min ago`;if(d<86400000)return `${Math.floor(d/3600000)} hr ago`;return new Date(value).toLocaleDateString(); };
async function api(url, options={}) { const response=await fetch(url,{...options,headers:{...(options.body instanceof FormData?{}:{"Content-Type":"application/json"}),...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data; }
function toast(message,error=false){const el=document.createElement("div");el.className="toast"+(error?" error":"");el.textContent=message;$("#toast-region").append(el);setTimeout(()=>el.remove(),3900);}
function setView(name){$$('.view').forEach(v=>v.classList.toggle("active",v.id===`view-${name}`));$$('.nav-item').forEach(b=>b.classList.toggle("active",b.dataset.view===name));const labels={home:"Discover",compare:"Compare offers",history:"Price history",wishlist:"Wishlist",alerts:"Price alerts",data:"My price data"};$("#crumb").textContent=tr(labels[name]||"Discover");$("#sidebar").classList.remove("open");if(name==="history"){const historyInput=$("#history-query"),discoverQuery=$("#search-input").value.trim();if(discoverQuery)historyInput.value=discoverQuery;else if(!historyInput.value.trim())historyInput.value=lastQuery;loadHistory();}if(name==="wishlist")loadWishlist();if(name==="alerts")loadAlerts();if(name==="compare"){renderCompare();loadComparisons();}if(name==="data")loadSummary();applyLanguage();}
function offerCard(item,index){const selectable=Boolean(item.product_id&&item.offer_id);const checked=compared.some(x=>x.offer_id===item.offer_id);return `<article class="offer-card"><div class="offer-top"><span class="store-chip">${storeBadge(item.store)}${safe(item.store)}</span><span class="offer-age">${safe(relative(item.checked_at))}</span></div><a class="offer-title" href="${safe(item.url)}" target="_blank" rel="noreferrer">${safe(item.title)}</a><div class="offer-meta">${safe(item.availability||tr('Availability not confirmed'))} · ${item.price?tr('Live price'):tr('Could not verify price')}</div><div class="offer-bottom"><div class="offer-price">${item.price?`${fmt(item.price,item.currency)}<small> · ${tr('checked live')}</small>`:`<small>${tr('Price unavailable')}</small>`}</div><div class="offer-actions">${selectable?`<button class="mini-button ${checked?'selected':''}" data-compare="${index}">${checked?'✓ '+tr('Added'):'⇄ '+tr('Compare')}</button><button class="mini-button" data-wishlist="${index}" title="${tr('Save')}">♡ ${tr('Save')}</button><button class="mini-button" data-alert="${index}" title="${tr('Alert')}">♧ ${tr('Alert')}</button>`:''}</div></div><a class="retailer-link" href="${safe(item.url)}" target="_blank" rel="noreferrer">${tr('View at')} ${safe(item.store)} ↗</a></article>`;}
async function search(query){
  query=(query||"").trim();
  if(query.length<2){toast(tr("Enter at least two characters to search."),true);return;}
  if(!selectedRetailers.size){toast(tr("Choose at least one store before searching."),true);return;}
  const stores=[...selectedRetailers];lastQuery=query;$("#search-input").value=query;$("#history-query").value=query;
  $("#results-heading").textContent=`${language==="sq"?"Po kërkohet":"Searching for"} “${query}”`;
  $("#results-subtitle").textContent=`${tr("Checking selected stores at the same time.")} · ${stores.length} ${tr("stores selected")}`;
  $("#search-progress").classList.remove("complete");$("#search-progress-label").textContent=tr("Checking retailer listings…");$("#search-progress-detail").textContent=`${stores.length} ${tr("stores selected")}`;$("#search-progress").hidden=false;$("#home-empty").hidden=true;$("#result-tools").hidden=true;$("#store-status").innerHTML="";$("#results-grid").innerHTML="";
  let failed=false;
  try{
    const data=await api("/api/search",{method:"POST",body:JSON.stringify({query,stores})});liveResults=data.results||[];renderResults();
    const matchedStores=new Set(liveResults.map(x=>x.store)),selected=data.stores||stores;
    $("#store-status").innerHTML=selected.map(name=>{const error=data.errors.some(e=>e.store===name),matched=matchedStores.has(name),state=error?"failed":matched?"ok":"no-match",label=error?"Unavailable":matched?"Matches found":"No matching listings",description=error?"The store could not be reached.":matched?"Matching listings were found.":"The store responded, but no matching listing was found in its catalogue.";return `<div class="store-status ${state}" title="${description}">${storeBadge(name)}${safe(name)}<span class="store-check">${tr(label)}</span></div>`;}).join("");
    $("#results-heading").textContent=language==="sq"?`${liveResults.length} oferta përputhëse`:`${liveResults.length} matching listings`;$("#results-subtitle").textContent=`${tr("Results for")} “${data.canonical_query}” · ${language==="sq"?"kontrolluar":"checked"} ${new Date(data.checked_at).toLocaleTimeString()}`;failed=Boolean(data.errors.length);if(failed)toast(`${data.errors.length} ${language==="sq"?"dyqane nuk u arritën":"store(s) could not be reached"}. ${language==="sq"?"Rezultatet e tjera shfaqen.":"Other results are shown."}`,true);if(!liveResults.length)$("#home-empty").hidden=false;await loadSummary();
  }catch(e){failed=true;$("#results-heading").textContent=tr("Search could not be completed");$("#results-subtitle").textContent=e.message;$("#home-empty").hidden=false;$("#home-empty b").textContent=language==="sq"?"Rezultatet nuk u ngarkuan.":"We couldn't load store results.";$("#home-empty span").textContent=language==="sq"?"Kontrollo lidhjen dhe provo sërish.":"Check your connection and retry. Retailer access can be temporarily unavailable.";toast(e.message,true);}
  finally{$("#search-progress").classList.add("complete");$("#search-progress-label").textContent=tr(failed?"Search finished with some store errors":"Search finished");$("#search-progress-detail").textContent=language==="sq"?`${liveResults.length} oferta nga ${stores.length} dyqane · çmimet në EUR renditen me kursin 1 € = 100 Lekë`:`${liveResults.length} listings from ${stores.length} stores · EUR sorted at €1 = Lekë 100`;$("#search-progress").hidden=false;applyLanguage();}
}
function renderResults(){const mode=$("#sort-select").value;const sorted=[...liveResults];if(mode==="price")sorted.sort((a,b)=>comparablePrice(a)-comparablePrice(b));if(mode==="store")sorted.sort((a,b)=>a.store.localeCompare(b.store));if(mode==="name")sorted.sort((a,b)=>a.title.localeCompare(b.title));$("#results-grid").innerHTML=sorted.map(item=>offerCard(item,liveResults.indexOf(item))).join("");$("#result-tools").hidden=!liveResults.length;$("#home-empty").hidden=Boolean(liveResults.length);$("#compare-selected-count").textContent=compared.length;$("#compare-count").textContent=compared.length;applyLanguage();}
function toggleCompare(index){const item=liveResults[index];if(!item?.offer_id)return;if(compared.some(x=>x.offer_id===item.offer_id))compared=compared.filter(x=>x.offer_id!==item.offer_id);else if(compared.length>=4){toast("Compare up to four offers at a time.",true);return;}else compared.push(item);renderResults();}
function renderCompare(){
  const root=$("#comparison-grid"),priced=compared.filter(x=>Number.isFinite(comparablePrice(x))).sort((a,b)=>comparablePrice(a)-comparablePrice(b));
  const cheapest=priced[0],highest=priced[priced.length-1],gap=cheapest&&highest?comparablePrice(highest)-comparablePrice(cheapest):0,maxPrice=highest?comparablePrice(highest):0;
  $("#compare-empty").hidden=compared.length>0;$("#compare-insights").hidden=priced.length===0;$("#compare-disclaimer").hidden=priced.length===0;
  $("#compare-title").textContent=compared.length?`${compared.length} ${tr("offers selected")}`:tr("No offers selected");
  $("#compare-caption").textContent=compared.length?(language==="sq"?"Ofertat renditen sipas çmimit të krahasueshëm; hap dyqanin për të verifikuar variantin.":"Ranked by comparable price; open each retailer listing to verify the exact variant."):tr("Select offers from Discover to add them here.");
  $("#compare-insights").innerHTML=priced.length?`<article class="insight-card best"><span>${tr("Lowest checked price")}</span><b>${fmt(cheapest.price,cheapest.currency)}</b><small>${safe(cheapest.store)} · ${tr("LOWEST CHECKED")}</small></article><article class="insight-card"><span>${tr("Potential saving")}</span><b>${priced.length>1?fmt(gap,"ALL"):"—"}</b><small>${tr("vs. highest selected offer")}</small></article><article class="insight-card"><span>${tr("Price spread")}</span><b>${priced.length>1?`${((comparablePrice(highest)-comparablePrice(cheapest))/comparablePrice(cheapest)*100).toLocaleString(language==="sq"?"sq-AL":"en-US",{maximumFractionDigits:1})}%`:"—"}</b><small>${priced.length} ${tr("priced offers")}</small></article>`:"";
  root.innerHTML=compared.map((x,i)=>{const amount=comparablePrice(x),best=cheapest&&x.offer_id===cheapest.offer_id,bar=maxPrice>0&&Number.isFinite(amount)?Math.max(5,amount/maxPrice*100):0,delta=cheapest&&Number.isFinite(amount)?amount-comparablePrice(cheapest):null;return `<article class="comparison-offer ${best?"is-best":""}"><div class="comparison-offer-head"><span class="store-chip">${storeBadge(x.store)}${safe(x.store)}</span>${best?`<span class="best-badge">✦ ${tr("LOWEST CHECKED")}</span>`:""}</div><a class="comparison-product" href="${safe(x.url)}" target="_blank" rel="noreferrer">${safe(x.title)}</a><div class="comparison-price">${fmt(x.price,x.currency)}</div>${x.currency==="EUR"?`<div class="price-converted">≈ ${fmt(amount,"ALL")} <span>${tr("Compared at €1 = 100 Lekë")}</span></div>`:""}<div class="comparison-meter" aria-label="${tr("Price position")}"><span style="width:${bar}%"></span></div><div class="comparison-delta">${best?tr("Lowest checked price"):delta===null?tr("Price unavailable"):`+${fmt(delta,"ALL")} ${tr("More than the lowest")}`}</div><div class="comparison-facts"><span>${tr("Availability")}</span><b>${safe(x.availability||"Unknown")}</b><span>${tr("Checked")}</span><b>${safe(relative(x.checked_at))}</b></div><div class="comparison-actions"><a class="retailer-link" href="${safe(x.url)}" target="_blank" rel="noreferrer">${tr("View retailer offer ↗")}</a><button class="mini-button" data-remove-compare="${i}">${tr("Remove")}</button></div></article>`;}).join("");
  applyLanguage();
}
async function saveComparison(){if(!compared.length){toast("Add offers before saving a comparison.",true);return;}try{await api("/api/comparisons",{method:"POST",body:JSON.stringify({query:lastQuery||"Saved comparison",items:compared})});toast("Comparison snapshot saved.");}catch(e){toast(e.message,true);}}
async function saveWishlist(item){try{await api("/api/wishlist",{method:"POST",body:JSON.stringify({product_id:item.product_id,offer_id:item.offer_id})});toast("Added to your wishlist.");await loadSummary();}catch(e){toast(e.message,true);}}
function openAlert(item){$("#alert-product-name").textContent=`${item.title} · ${item.store} · ${fmt(item.price,item.currency)}`;$("#alert-product-id").value=item.product_id;$("#alert-offer-id").value=item.offer_id;$("#alert-currency").value=item.currency||"ALL";$("#alert-kind").value="target";$("#alert-threshold").value="";updateAlertField();$("#alert-dialog").showModal();}
function updateAlertField(){const kind=$("#alert-kind").value,currency=$("#alert-currency").value||"ALL";$("#alert-threshold-wrap").hidden=!['target','drop'].includes(kind);$("#alert-threshold-label").textContent=kind==='drop'?tr("Drop percentage"):language==="sq"?`Çmimi i synuar (${currency==="EUR"?"EUR":"Lekë"})`:`Target price (${currency==="EUR"?"EUR":"Lekë"})`;$("#alert-threshold").placeholder=kind==='drop'?"e.g. 10":currency==='EUR'?"e.g. 1,250.50":"e.g. 120,000";}
function formatThreshold(){const input=$("#alert-threshold"),kind=$("#alert-kind").value,currency=$("#alert-currency").value||"ALL";if(kind==='drop')return;let raw=input.value.replace(/[^0-9.]/g,"");if(currency!=="EUR")raw=raw.split(".")[0];else{const p=raw.split(".");raw=p.shift()+(p.length?"."+p.join("").slice(0,2):"");}if(!raw)return;const parts=raw.split("."),whole=parts[0].replace(/^0+(?=\d)/,"");input.value=new Intl.NumberFormat("en-US",{maximumFractionDigits:0}).format(Number(whole||0))+(parts.length>1?"."+parts[1]:"");}
async function createAlert(){const kind=$("#alert-kind").value,currency=$("#alert-currency").value||"ALL",raw=$("#alert-threshold").value.replaceAll(",","");const threshold=raw?Number(raw):null;try{const data=await api("/api/alerts",{method:"POST",body:JSON.stringify({product_id:$("#alert-product-id").value,offer_id:$("#alert-offer-id").value,kind,threshold,currency})});$("#alert-dialog").close();toast(data.note||tr("Price rule created."));await loadSummary();}catch(e){toast(e.message,true);}}
async function loadWishlist(){try{const rows=await api("/api/wishlist");$("#wishlist-empty").hidden=rows.length>0;$("#wishlist-grid").innerHTML=rows.map(r=>`<article class="saved-card"><span class="store-chip">♡ SAVED${r.retailer?` · ${safe(r.retailer)}`:''}</span><h3>${safe(r.product_name)}</h3><p>${safe(r.category||'Technology')} · added ${new Date(r.created_at).toLocaleDateString()}</p><div class="offer-price">${r.latest_price?fmt(r.latest_price,r.currency):'Waiting for a fresh price check'}</div>${r.target_price?`<p>Target: ${fmt(r.target_price,r.currency||'ALL')}</p>`:''}<div class="saved-actions"><a class="retailer-link" href="${safe(r.url||'#')}" target="_blank" rel="noreferrer">Open offer ↗</a><button class="mini-button" data-delete-wish="${r.id}">Remove</button></div></article>`).join("");}catch(e){toast(e.message,true);}}
async function loadAlerts(){try{const data=await api("/api/alerts");const rows=data.alerts||[];$("#alerts-empty").hidden=rows.length>0;$("#alerts-list").innerHTML=rows.map(a=>`<article class="saved-card"><span class="store-chip"><i class="status-dot"></i>${a.active?'ACTIVE':'PAUSED'} · ${safe(a.retailer||'All saved retailers')}</span><h3>${safe(a.product_name)}</h3><p>${safe(a.kind.replaceAll('_',' '))}${a.threshold?` · ${a.kind==='drop'?a.threshold+'%':fmt(a.threshold,a.currency||'ALL')}`:''}</p><div class="offer-price">${a.latest_price?fmt(a.latest_price,a.currency):'Waiting for a fresh check'}</div><div class="saved-actions"><button class="mini-button" data-toggle-alert="${a.id}" data-active="${a.active?0:1}">${a.active?'Pause':'Resume'}</button><button class="mini-button" data-delete-alert="${a.id}">Remove</button></div></article>`).join("");const notes=data.notifications||[];$("#notification-list").innerHTML=notes.length?notes.map(n=>`<div class="notification-row ${n.read_at?'':'unread'}"><div>${safe(n.message)}<small>${new Date(n.created_at).toLocaleString()}</small></div></div>`).join(""):"<div class='muted' style='padding:16px;font-size:10px'>No triggered alerts yet.</div>";$("#notification-dot").style.display=notes.some(n=>!n.read_at)?"block":"none";}catch(e){toast(e.message,true);}}
function historyQueryMatch(row,query){
  const accessory=/\b(case|cover|protector|tempered|glass|charger|cable|adapter|powerbank|holder|mount|stand|sleeve|pouch|skin|strap|earbuds|headphones|keyboard|mouse|stylus|kase|xhami|mbrojtes)\b/i;
  if(query&&accessory.test(row.product_name||""))return false;
  const q=(query||"").toLocaleLowerCase().replace(/miniled/g,"mini led").normalize("NFD").replace(/[\u0300-\u036f]/g,"").match(/[a-z0-9]+/g)||[];
  const name=(row.product_name||"").toLocaleLowerCase().replace(/miniled/g,"mini led").normalize("NFD").replace(/[\u0300-\u036f]/g,"");
  if(!q.length)return true;
  const hits=q.filter(token=>name.includes(token)).length;
  return hits/q.length>=.75;
}
function renderHistoryStores(){
  const root=$("#history-stores"),names=[...new Set(historyRows.map(r=>r.source))].sort((a,b)=>a.localeCompare(b));
  if(selectedHistoryStores)selectedHistoryStores=new Set([...selectedHistoryStores].filter(x=>names.includes(x)));
  $("#history-stores-all").disabled=!names.length;$("#history-stores-all").classList.toggle("active",!selectedHistoryStores);
  root.innerHTML=names.length?names.map(name=>`<label class="history-store-option"><input type="checkbox" data-history-store="${safe(name)}" ${!selectedHistoryStores||selectedHistoryStores.has(name)?"checked":""}><span class="history-store-name">${storeBadge(name)}<b>${safe(name)}</b></span><small>${tr("Matches found")}</small></label>`).join(""):`<span class="history-store-empty">${tr("No saved prices match this search and time range.")}</span>`;
}
function renderHistoryRowsAndChart(){
  const rows=selectedHistoryStores?historyRows.filter(r=>selectedHistoryStores.has(r.source)):historyRows;
  const storeCount=new Set(rows.map(r=>r.source)).size;
  $("#history-count").textContent=`${rows.length.toLocaleString()} ${tr("recorded prices")} · ${storeCount} ${language==="sq"?"dyqane":"stores"}`;
  const shown=rows.slice().reverse().slice(0,100);
  $("#history-rows").innerHTML=shown.map(r=>`<tr><td>${safe(r.product_name)}</td><td>${safe(r.source)}</td><td class="price-cell">${fmt(r.price,r.currency)}</td><td>${new Date(r.observed_at).toLocaleString()}</td><td>${safe(r.availability||"unknown")}</td></tr>`).join("");
  $("#history-table-note").textContent=rows.length>shown.length?`${tr("Showing latest 100 of")} ${rows.length.toLocaleString()} ${tr("recorded prices")}`:tr("All matching observations are shown.");
  $("#chart-empty").hidden=rows.length>0;if(!rows.length)$("#chart-empty").textContent=tr("No saved prices match this search and time range.");drawChart(rows);
}
async function loadHistory(){
  try{
    const q=$("#history-query").value.trim(),all=await api("/api/history?days=90"),now=new Date();let cutoff=new Date(now);
    if(historyRange==="today"){cutoff.setHours(0,0,0,0);}else if(historyRange==="week"){cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-((cutoff.getDay()+6)%7));}else if(historyRange==="month"){cutoff=new Date(now.getFullYear(),now.getMonth(),1);}else{cutoff.setDate(cutoff.getDate()-90);}
    historyRows=all.filter(r=>historyQueryMatch(r,q)&&new Date(r.observed_at)>=cutoff&&new Date(r.observed_at)<=now);
    renderHistoryStores();renderHistoryRowsAndChart();
  }catch(e){toast(e.message,true);}
}
function drawChart(rows){
  const canvas=$("#history-chart"),ctx=canvas.getContext("2d"),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;
  canvas.width=Math.max(1,rect.width*dpr);canvas.height=Math.max(1,rect.height*dpr);ctx.scale(dpr,dpr);ctx.clearRect(0,0,rect.width,rect.height);$("#chart-legend").innerHTML="";
  const valid=rows.filter(r=>Number.isFinite(Number(r.price))&&Number(r.price)>0);if(!valid.length){$("#history-chart-note").textContent=tr("No saved prices match this product and time range.");return;}
  const days=[...new Set(valid.map(r=>new Date(r.observed_at).toLocaleDateString()))];
  const seriesMode=days.length>1;$("#history-chart-note").textContent=`${tr(seriesMode?"Daily lowest price by retailer":"Lowest saved price by retailer")} · ${tr("Prices shown as Lekë equivalent (€1 = 100 Lekë).")}`;
  const normalized=valid.map(r=>({...r,plotPrice:comparablePrice({price:Number(r.price),currency:r.currency})}));
  const pad={l:64,r:24,t:20,b:38},w=Math.max(20,rect.width-pad.l-pad.r),h=Math.max(20,rect.height-pad.t-pad.b);
  const vals=normalized.map(r=>r.plotPrice),min=Math.min(...vals),max=Math.max(...vals),span=max-min||Math.max(max*.12,1000),yMin=Math.max(0,min-span*.15),yMax=max+span*.15;
  ctx.font="11px DM Sans";ctx.lineWidth=1;ctx.strokeStyle="#26362b";ctx.fillStyle="#849187";
  for(let i=0;i<5;i++){const y=pad.t+h*i/4,v=yMax-(yMax-yMin)*i/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+w,y);ctx.stroke();ctx.textAlign="right";ctx.fillText(new Intl.NumberFormat(language==="sq"?"sq-AL":"en-US",{notation:"compact",maximumFractionDigits:1}).format(v),pad.l-10,y+4);}
  if(!seriesMode){
    const groups={};normalized.forEach(r=>{(groups[r.source]??=[]).push(r);});const items=Object.entries(groups).map(([name,points])=>({name,price:Math.min(...points.map(p=>p.plotPrice)),color:palette[Math.max(0,retailers.indexOf(name))%palette.length]})).sort((a,b)=>a.price-b.price);
    const rowH=Math.min(34,h/Math.max(items.length,1)),barMax=Math.max(...items.map(x=>x.price));items.forEach((item,i)=>{const y=pad.t+i*rowH+rowH*.2,bh=Math.max(9,rowH*.56),bw=item.price/barMax*w;ctx.fillStyle="#19271d";ctx.beginPath();ctx.roundRect(pad.l,y,w,bh,5);ctx.fill();ctx.fillStyle=item.color;ctx.beginPath();ctx.roundRect(pad.l,y,bw,bh,5);ctx.fill();ctx.fillStyle="#e5eee6";ctx.font="700 10px DM Sans";ctx.textAlign="left";ctx.fillText(fmt(item.price,"ALL"),Math.max(pad.l+4,Math.min(pad.l+bw+8,pad.l+w-76)),y+bh*.8);$("#chart-legend").insertAdjacentHTML("beforeend",`<span><i class="legend-dot" style="background:${item.color}"></i>${safe(item.name)} · ${fmt(item.price,"ALL")}</span>`);});
  }else{
    const groups={};normalized.forEach(r=>{(groups[r.source]??=[]).push(r);});const x0=Math.min(...normalized.map(r=>new Date(r.observed_at).getTime())),x1=Math.max(...normalized.map(r=>new Date(r.observed_at).getTime()));
    Object.entries(groups).forEach(([name,points])=>{const daily={};points.forEach(p=>{const key=new Date(p.observed_at).toISOString().slice(0,10);if(!daily[key]||p.plotPrice<daily[key].plotPrice)daily[key]=p;});points=Object.values(daily).sort((a,b)=>new Date(a.observed_at)-new Date(b.observed_at));const color=palette[Math.max(0,retailers.indexOf(name))%palette.length];ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=2.5;ctx.beginPath();points.forEach((p,i)=>{const x=pad.l+((new Date(p.observed_at).getTime()-x0)/(x1-x0||1))*w,y=pad.t+(yMax-p.plotPrice)/(yMax-yMin)*h;if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);});ctx.stroke();points.forEach(p=>{const x=pad.l+((new Date(p.observed_at).getTime()-x0)/(x1-x0||1))*w,y=pad.t+(yMax-p.plotPrice)/(yMax-yMin)*h;ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fill();});$("#chart-legend").insertAdjacentHTML("beforeend",`<span><i class="legend-dot" style="background:${color}"></i>${safe(name)}</span>`);});
    ctx.fillStyle="#849187";ctx.font="10px DM Sans";ctx.textAlign="center";for(let i=0;i<5;i++){const t=x0+(x1-x0)*i/4,label=new Date(t).toLocaleDateString(language==="sq"?"sq-AL":"en-GB",{day:"2-digit",month:"short"});ctx.fillText(label,pad.l+w*i/4,rect.height-12);}
  }
}
async function loadSummary(){try{const s=await api("/api/summary");$("#stat-observations").textContent=s.observations.toLocaleString();$("#data-products").textContent=s.products.toLocaleString();$("#data-offers").textContent=s.offers.toLocaleString();$("#data-observations").textContent=s.observations.toLocaleString();$("#wish-count").textContent=s.wishlist;$("#alert-count").textContent=s.alerts;}catch{}}
async function importCsv(event){event.preventDefault();const file=$("#csv-file").files[0];if(!file)return;const form=new FormData();form.append("file",file);$("#import-feedback").textContent="Importing…";try{const result=await api("/api/import/csv",{method:"POST",body:form});$("#import-feedback").textContent=result.message;toast(result.message);await loadSummary();}catch(e){$("#import-feedback").textContent=e.message;toast(e.message,true);}}
async function exportCsv(){try{const rows=await api("/api/history?days=0");const head=["Site","Product Name","Price","Currency","URL","Date","Time","Availability"];const esc=x=>'"'+String(x??'').replaceAll('"','""')+'"';const body=rows.map(r=>{const d=new Date(r.observed_at);return[r.source,r.product_name,r.price,r.currency,r.url,d.toISOString().slice(0,10),d.toISOString().slice(11,19),r.availability].map(esc).join(',')});const blob=new Blob([[head.map(esc).join(','),...body].join('\r\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='PricePal-price-history.csv';a.click();URL.revokeObjectURL(a.href);}catch(e){toast(e.message,true);}}
async function loadComparisons(){try{const items=await api("/api/comparisons");$("#saved-comparisons").innerHTML=items.length?items.map(c=>`<div class="notification-row"><div><button class="mini-button" data-open-comparison="${c.id}">${safe(c.query)} · ${c.snapshot.length} offers</button><small>${new Date(c.created_at).toLocaleString()}</small></div></div>`).join(""):"<div class='muted' style='padding:16px;font-size:10px'>No saved snapshots yet.</div>";}catch(e){toast(e.message,true);}}
async function openComparison(id){try{const items=await api("/api/comparisons");const c=items.find(x=>x.id===Number(id));if(!c)return;compared=c.snapshot||[];renderCompare();toast(`Opened saved comparison: ${c.query}`);}catch(e){toast(e.message,true);}}
document.addEventListener("click",async e=>{const range=e.target.closest("[data-history-range]");if(range){historyRange=range.dataset.historyRange;$$ ("[data-history-range]").forEach(b=>b.classList.toggle("active",b===range));loadHistory();return;}const allStores=e.target.closest("#history-stores-all");if(allStores){selectedHistoryStores=null;renderHistoryStores();renderHistoryRowsAndChart();return;}const nav=e.target.closest("[data-view]");if(nav){setView(nav.dataset.view);return;}const go=e.target.closest("[data-go]");if(go){setView(go.dataset.go);return;}const sug=e.target.closest(".suggestion");if(sug){search(sug.textContent);return;}const cp=e.target.closest("[data-compare]");if(cp){toggleCompare(Number(cp.dataset.compare));return;}const wish=e.target.closest("[data-wishlist]");if(wish){await saveWishlist(liveResults[Number(wish.dataset.wishlist)]);return;}const al=e.target.closest("[data-alert]");if(al){openAlert(liveResults[Number(al.dataset.alert)]);return;}const rem=e.target.closest("[data-remove-compare]");if(rem){compared.splice(Number(rem.dataset.removeCompare),1);renderCompare();renderResults();return;}const dw=e.target.closest("[data-delete-wish]");if(dw){await api(`/api/wishlist/${dw.dataset.deleteWish}`,{method:"DELETE"});await loadWishlist();await loadSummary();toast("Removed from wishlist.");return;}const ta=e.target.closest("[data-toggle-alert]");if(ta){await api(`/api/alerts/${ta.dataset.toggleAlert}`,{method:"PATCH",body:JSON.stringify({active:ta.dataset.active==="1"})});await loadAlerts();await loadSummary();return;}const da=e.target.closest("[data-delete-alert]");if(da){await api(`/api/alerts/${da.dataset.deleteAlert}`,{method:"DELETE"});await loadAlerts();await loadSummary();toast("Alert removed.");return;}const open=e.target.closest("[data-open-comparison]");if(open){await openComparison(open.dataset.openComparison);return;}});
$("#retailer-picker-list").addEventListener("click",e=>{const card=e.target.closest("[data-select-retailer]");if(!card)return;const name=card.dataset.selectRetailer;if(selectedRetailers.has(name))selectedRetailers.delete(name);else selectedRetailers.add(name);localStorage.setItem("pricepal-selected-retailers",JSON.stringify([...selectedRetailers]));renderRetailerPicker();});$("#retailer-select-all").addEventListener("change",e=>{selectedRetailers=e.target.checked?new Set(retailers):new Set();localStorage.setItem("pricepal-selected-retailers",JSON.stringify([...selectedRetailers]));renderRetailerPicker();});$("#history-stores").addEventListener("change",e=>{if(!e.target.matches("[data-history-store]"))return;const names=[...new Set(historyRows.map(r=>r.source))],checked=new Set($$ ("[data-history-store]:checked").map(el=>el.dataset.historyStore));selectedHistoryStores=checked.size===names.length?null:checked;renderHistoryStores();renderHistoryRowsAndChart();});$("#search-form").addEventListener("submit",e=>{e.preventDefault();search($("#search-input").value);});$("#sort-select").addEventListener("change",renderResults);$("#compare-selected").addEventListener("click",()=>{if(!compared.length){toast(tr("Select at least one offer first."),true);return;}setView("compare");renderCompare();});$("#save-comparison").addEventListener("click",saveComparison);$("#alert-kind").addEventListener("change",updateAlertField);$("#alert-threshold").addEventListener("input",formatThreshold);$("#create-alert").addEventListener("click",createAlert);$("#alert-close").addEventListener("click",()=>$("#alert-dialog").close());$("#alert-form").addEventListener("submit",e=>e.preventDefault());$("#alert-dialog").addEventListener("click",e=>{if(e.target===$("#alert-dialog"))$("#alert-dialog").close();});$("#history-query").addEventListener("input",()=>{clearTimeout(window._historyTimer);window._historyTimer=setTimeout(loadHistory,250);});$("#import-form").addEventListener("submit",importCsv);$("#export-csv").addEventListener("click",exportCsv);$("#notify-button").addEventListener("click",()=>{setView("alerts");loadAlerts();});$("#mark-read").addEventListener("click",async()=>{await api("/api/notifications/read",{method:"POST",body:"{}"});await loadAlerts();toast("Notifications marked as read.");});$("#mobile-menu").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));$("#language-toggle").addEventListener("click",()=>{language=language==="en"?"sq":"en";localStorage.setItem("pricepal-language",language);applyLanguage();updateAlertField();renderResults();renderCompare();if($("#view-alerts").classList.contains("active"))loadAlerts();if($("#view-wishlist").classList.contains("active"))loadWishlist();});window.addEventListener("resize",()=>{if($("#view-history").classList.contains("active"))drawChart(historyRows);});const translationObserver=new MutationObserver(()=>{if(!window._languageFrame){window._languageFrame=requestAnimationFrame(()=>{window._languageFrame=0;applyLanguage();});}});translationObserver.observe(document.body,{subtree:true,childList:true,characterData:true});renderRetailerPicker();applyLanguage();loadSummary();
